(()=>{
  const STYLE_ID='ymMotorGuidedV3Styles';
  if(document.getElementById(STYLE_ID)) return;
  const style=document.createElement('style');
  style.id=STYLE_ID;
  style.textContent=`
  .vosg-wrap{display:grid;gap:12px}.vosg-hero{background:linear-gradient(135deg,#0a2540,#174c78 72%,#484dcf);color:#fff;border-radius:20px;padding:20px 22px;box-shadow:var(--ym-shadow)}
  .vosg-eyebrow{font:800 10px Montserrat;letter-spacing:.06em;color:#bfd2ff;text-transform:uppercase}.vosg-hero h2{font:800 24px Montserrat;margin:6px 0}.vosg-hero p{font-size:12px;line-height:1.5;color:#d4e1ec;margin:0}.vosg-progress{display:grid;grid-template-columns:repeat(6,1fr);gap:7px;margin-top:12px}.vosg-step{border:1px solid rgba(255,255,255,.24);background:rgba(255,255,255,.08);color:#fff;border-radius:10px;padding:9px 8px;cursor:pointer;text-align:center;font:700 9px Montserrat}.vosg-step.active{background:#fff;color:#0a2540}.vosg-step.done:before{content:'✓ ';color:#5be0a2}.vosg-card{background:#fff;border:1px solid #dce5ee;border-radius:16px;box-shadow:0 8px 24px rgba(15,42,67,.06);padding:17px}.vosg-card h3{font:800 16px Montserrat;color:#0a2540;margin:0 0 6px}.vosg-card h4{font:800 12px Montserrat;color:#0a2540;margin:0}.vosg-copy{font-size:12px;line-height:1.6;color:#425d72}.vosg-muted{font-size:10.5px;line-height:1.5;color:#6a7f91}.vosg-kicker{font:800 9px Montserrat;letter-spacing:.06em;text-transform:uppercase;color:#484dcf;margin-bottom:5px}.vosg-callout{border-radius:12px;padding:12px 13px;border:1px solid #d8e3ee;background:#f8fbfe;margin:10px 0}.vosg-callout.amber{background:#fff9eb;border-color:#eddcb5}.vosg-callout.green{background:#f2fbf7;border-color:#cfe9db}.vosg-callout.blue{background:#f2f6ff;border-color:#d4dff8}.vosg-callout.red{background:#fff6f6;border-color:#eccccc}.vosg-grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}.vosg-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.vosg-actions .ym-btn{font-size:11px;padding:10px 13px}.vosg-nav{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:14px;padding-top:12px;border-top:1px solid #edf1f5}.vosg-term{display:inline-flex;align-items:center;gap:4px;font-size:10px;color:#4b63bd;background:#f0f3ff;border:1px solid #dce2fb;border-radius:999px;padding:4px 7px;cursor:pointer}.vosg-term:hover{background:#e9edff}.vosg-form label{display:block;font:800 10px Montserrat;color:#17364f;margin:11px 0 5px}.vosg-form textarea,.vosg-form input,.vosg-form select{font-size:12px!important;line-height:1.45}.vosg-pchips,.vosg-hchips{display:flex;gap:6px;overflow:auto;padding:2px 0 8px}.vosg-chip{border:1px solid #dce4ed;background:#fff;border-radius:999px;padding:7px 10px;white-space:nowrap;font-size:9.5px;color:#526b7e;cursor:pointer}.vosg-chip.active{background:#0a2540;border-color:#0a2540;color:#fff}.vosg-chip.ok{border-color:#b9dec9;background:#f5fcf8}.vosg-question{display:grid;grid-template-columns:minmax(0,1fr) 190px;gap:10px;align-items:center;padding:10px;border:1px solid #e4eaf0;border-radius:10px;margin-top:7px;background:#fcfdff}.vosg-question span{font-size:11px;line-height:1.5;color:#3d586e}.vosg-question select{font-size:11px}.vosg-list{margin:5px 0 0;padding-left:18px}.vosg-list li{font-size:11.5px;line-height:1.5;color:#425d72;margin:4px 0}.vosg-invest-step{border:1px solid #e0e7ee;border-radius:12px;padding:12px;margin-top:9px;background:#fff}.vosg-invest-step .num{display:inline-grid;place-items:center;width:25px;height:25px;border-radius:8px;background:#0a2540;color:#fff;font:800 10px Montserrat;margin-right:7px}.vosg-invest-step textarea{margin-top:8px}.vosg-choice{display:grid;gap:7px;margin-top:9px}.vosg-choice label{display:flex;gap:9px;align-items:flex-start;border:1px solid #dfe6ed;border-radius:11px;padding:10px;cursor:pointer;background:#fff}.vosg-choice label:hover{background:#f8fbfe}.vosg-choice b{font-size:11px;color:#17364f;display:block}.vosg-choice span{font-size:10px;line-height:1.45;color:#63798b}.vosg-status{display:flex;gap:7px;flex-wrap:wrap}.vosg-status span{font-size:9px;border-radius:999px;padding:5px 8px;background:#f1f4f7;color:#536a7d}.vosg-status .ok{background:#eaf8f0;color:#276746}.vosg-status .warn{background:#fff4dc;color:#7a5710}.vosg-history{margin-top:10px}.vosg-history details{border:1px solid #e1e7ed;border-radius:10px;padding:9px 10px;background:#fbfcfd}.vosg-history summary{cursor:pointer;font:700 10px Montserrat;color:#17364f}.vosg-history pre{white-space:pre-wrap;font:10px/1.5 Inter,Arial,sans-serif;color:#425d72;margin:8px 0 0}.vosg-glossary-btn{border:0;background:transparent;color:#e0eaff;text-decoration:underline;cursor:pointer;font-size:10px;padding:0}.vosg-modal{position:fixed;inset:0;z-index:99999;background:rgba(7,24,40,.66);display:grid;place-items:center;padding:14px}.vosg-modal-card{width:min(900px,100%);max-height:92vh;overflow:auto;background:#fff;border-radius:18px;box-shadow:0 30px 90px rgba(0,0,0,.3)}.vosg-modal-head{position:sticky;top:0;background:linear-gradient(135deg,#0a2540,#174c78);color:#fff;padding:14px 16px;display:flex;justify-content:space-between;gap:10px;align-items:flex-start;z-index:2}.vosg-modal-head b{font:800 13px Montserrat}.vosg-modal-head p{font-size:10px;color:#d5e1eb;margin:4px 0 0}.vosg-close{border:0;background:rgba(255,255,255,.12);color:#fff;border-radius:9px;width:34px;height:34px;font-size:18px;cursor:pointer}.vosg-modal-body{padding:15px 16px}.vosg-modal-body textarea{min-height:180px}.vosg-prompt{min-height:260px!important;font:10px/1.5 Inter,Arial,sans-serif!important;background:#f8fafc!important}.vosg-divider{height:1px;background:#e9eef3;margin:14px 0}.vosg-gloss{display:grid;gap:9px}.vosg-gloss>div{border:1px solid #e0e7ee;border-radius:11px;padding:10px}.vosg-gloss b{font:800 10px Montserrat;color:#0a2540}.vosg-gloss p{font-size:11px;line-height:1.5;color:#4b6579;margin:4px 0 0}.vosg-technical{margin-top:10px}.vosg-technical summary{cursor:pointer;font-size:10px;color:#687d8e}.vosg-order{display:grid;grid-template-columns:34px 1fr;gap:10px;border:1px solid #e1e8ef;border-radius:11px;padding:10px;margin-top:8px}.vosg-order .seq{width:30px;height:30px;border-radius:9px;background:#0a2540;color:#fff;display:grid;place-items:center;font:800 10px Montserrat}.vosg-empty{text-align:center;padding:18px;border:1px dashed #ccd7e0;border-radius:12px;color:#6a7f91;font-size:11px;background:#fbfcfd}
  @media(max-width:900px){.vosg-progress{grid-template-columns:repeat(3,1fr)}.vosg-grid2{grid-template-columns:1fr}.vosg-question{grid-template-columns:1fr}}
  @media(max-width:600px){.vosg-card{padding:13px}.vosg-hero{padding:16px}.vosg-hero h2{font-size:20px}.vosg-progress{grid-template-columns:repeat(2,1fr)}.vosg-actions .ym-btn{flex:1 1 150px}.vosg-nav{align-items:stretch;flex-direction:column}.vosg-nav .ym-btn{width:100%}}
  `;
  document.head.appendChild(style);

  const E=v=>YM.esc(v??'');
  const state={caseId:null,step:1,p8Index:0,hypIndex:0,investIndex:0};
  const PLAIN={
    PRODUTO:{title:'Oferta',method:'Produto',what:'O que a empresa vende, para quem e qual resultado entrega.'},
    PRECO:{title:'Preço e valor',method:'Preço',what:'Como o preço é definido e se o cliente entende o que recebe pelo valor.'},
    PRACA:{title:'Como o cliente encontra a empresa',method:'Praça',what:'Onde o cliente encontra o negócio e como avança até orçamento, agendamento ou compra.'},
    PROMOCAO:{title:'Comunicação',method:'Promoção',what:'Se a comunicação ajuda o público a entender a empresa, a oferta e o próximo passo.'},
    PESSOAS:{title:'Pessoas e responsabilidades',method:'Pessoas',what:'Quem atende, vende, entrega e se a operação suporta a demanda.'},
    PROCESSOS:{title:'Como o trabalho acontece',method:'Processos',what:'Se existe um caminho repetível do primeiro contato até venda, entrega e acompanhamento.'},
    EVIDENCIAS_FISICAS:{title:'Provas e confiança',method:'Evidências físicas',what:'Quais provas existem de que o trabalho é real, confiável e funciona.'},
    PRODUTIVIDADE_QUALIDADE:{title:'Medição e qualidade',method:'Produtividade e Qualidade',what:'O que é acompanhado para saber se operação e entrega estão funcionando bem.'}
  };
  const CLASS_LABEL={ATIVO:'Funciona bem / é um ponto forte',DISFUNCAO:'Há algo que merece investigação',LACUNA:'Falta informação',INCONCLUSIVO:'Ainda não dá para concluir'};
  const CONF_LABEL={ALTA:'Alta — verifiquei bem',MEDIA:'Média — tenho bons sinais',BAIXA:'Baixa — ainda tenho dúvida',SEM_BASE:'Sem base — não consegui verificar'};
  const RESULT_LABEL={SUPORTA:'Há sinais que sustentam esta explicação',CONTRADIZ:'Os dados apontam contra esta explicação',INCONCLUSIVO:'Ainda não temos informação suficiente'};
  const FINAL_HYP=new Set(['VALIDADA','REJEITADA','INCONCLUSIVA']);

  function remember(){if(!currentId)return;try{localStorage.setItem('vos-guided-state:'+currentId,JSON.stringify({step:state.step,p8Index:state.p8Index,hypIndex:state.hypIndex,investIndex:state.investIndex}))}catch{}}
  function restore(){if(state.caseId===currentId)return;state.caseId=currentId;state.step=1;state.p8Index=0;state.hypIndex=0;state.investIndex=0;try{const x=JSON.parse(localStorage.getItem('vos-guided-state:'+currentId)||'null');if(x){state.step=Math.max(1,Math.min(6,Number(x.step)||1));state.p8Index=Math.max(0,Number(x.p8Index)||0);state.hypIndex=Math.max(0,Number(x.hypIndex)||0);state.investIndex=Math.max(0,Number(x.investIndex)||0)}}catch{}}
  function q(v){return String(v||'').replaceAll('_',' ')}
  function arr(v){return Array.isArray(v)?v:[]}
  function pInfo(p){return PLAIN[p?.p8_code]||{title:p?.p8_label||p?.p8_code||'Pilar',method:p?.p8_label||p?.p8_code||'Pilar',what:'Parte do negócio que precisa ser verificada.'}}
  function gate(){return arr(bundle?.gates)[0]||{}}
  function p8Done(){return arr(bundle?.p8_coverage).filter(x=>x.human_status==='VALIDADO').length}
  function hypPending(){return arr(bundle?.hypotheses).filter(h=>!FINAL_HYP.has(h.status)).length}
  function readyConclusion(){return p8Done()===8&&hypPending()===0}
  function currentStatus(step){
    const g=gate(), conc=arr(bundle?.conclusions).length, hy=arr(bundle?.hypotheses);
    if(step===1)return Boolean(bundle?.case?.destination_short_term);
    if(step===2)return p8Done()===8;
    if(step===3)return hy.length>0&&hy.every(h=>analysisFor(h).source!=='none');
    if(step===4)return hy.length>0&&hy.every(h=>FINAL_HYP.has(h.status));
    if(step===5)return g.status==='APROVADO'&&conc>0;
    return g.status==='APROVADO';
  }
  function stepBar(){const names=['Objetivo','Revisar negócio','Entender o que investigar','Registrar o que encontramos','Concluir o VER','Ordenar'];return `<div class="vosg-progress">${names.map((n,i)=>`<button class="vosg-step ${state.step===i+1?'active':''} ${currentStatus(i+1)?'done':''}" onclick="vosGoStep(${i+1})">${i+1}. ${E(n)}</button>`).join('')}</div>`}
  function nav(prev,next,nextLabel='Continuar'){return `<div class="vosg-nav"><div>${prev?`<button class="ym-btn secondary" onclick="vosGoStep(${prev})">← Voltar</button>`:''}</div><div>${next?`<button class="ym-btn" onclick="vosGoStep(${next})">${E(nextLabel)} →</button>`:''}</div></div>`}
  function term(label,desc){return `<span class="vosg-term" title="${E(desc)}" onclick="vosOpenGlossary()">${E(label)} · ?</span>`}
  function listHtml(xs){return arr(xs).length?`<ul class="vosg-list">${arr(xs).map(x=>`<li>${E(x)}</li>`).join('')}</ul>`:'<div class="vosg-muted">Nenhum item registrado.</div>'}

  function manualHistory(hid){
    return arr(bundle?.ver_entries).filter(e=>e?.source_type==='AI_SUGGESTION'&&String(e?.source_ref||'').startsWith('CHATGPT_MANUAL/'+hid+'/')).sort((a,b)=>String(a.source_ref).localeCompare(String(b.source_ref)));
  }
  function cleanHeading(s){return String(s||'').replace(/^\s*#{1,6}\s*/,'').replace(/\*\*/g,'').replace(/^>\s*/,'').trim()}
  function parseManual(text){
    const titles={
      'O QUE A IA ESTÁ VENDO':'leitura_ia','HIPÓTESE QUE VALE INVESTIGAR':'hipotese','POR QUE ISSO PODE IMPORTAR':'por_que_importa','O QUE JÁ TEMOS DE EVIDÊNCIA':'evidencias','O QUE AINDA PRECISAMOS DESCOBRIR':'faltas','A PERGUNTA QUE O TESTE PRECISA RESPONDER':'pergunta','COMO VALIDAR NA PRÁTICA':'validar','LEITURA PRELIMINAR DA IA':'prelim','SUGESTÃO PARA O CAMPO “O QUE VOCÊ ENCONTROU?”':'sugestao','SUGESTÃO PARA O CAMPO "O QUE VOCÊ ENCONTROU?"':'sugestao'
    };
    const sec={};let key=null;
    String(text||'').replace(/\r/g,'').split('\n').forEach(line=>{const c=cleanHeading(line).replace(/:$/,'').toUpperCase();const k=titles[c];if(k){key=k;sec[key]=[];return}if(key)sec[key].push(line)});
    const txt=k=>(sec[k]||[]).join('\n').trim().replace(/^>\s*/gm,'').replace(/\*\*/g,'').trim();
    const bullets=k=>{const raw=txt(k);if(!raw)return[];const lines=raw.split('\n').map(x=>x.trim()).filter(Boolean);const out=[];let buf='';for(const line of lines){if(/^[-•*]\s+/.test(line)||/^\d+[.)]\s+/.test(line)){if(buf)out.push(buf.trim());buf=line.replace(/^[-•*]\s+/,'').replace(/^\d+[.)]\s+/,'')}else if(buf)buf+=' '+line;else buf=line}if(buf)out.push(buf.trim());return out.length?out:[raw]};
    const prelim=txt('prelim'),res=(prelim.match(/\b(SUPORTA|CONTRADIZ|INCONCLUSIVO)\b/i)||[])[1]||'',conf=(prelim.match(/\b(ALTA|MEDIA|MÉDIA|BAIXA)\b/i)||[])[1]||'';
    return {leitura_ia:txt('leitura_ia'),hipotese:txt('hipotese'),por_que_importa:txt('por_que_importa'),evidencias_ja_existentes:bullets('evidencias'),o_que_falta_descobrir:bullets('faltas'),pergunta_central:txt('pergunta'),como_validar:bullets('validar'),resultado_preliminar:res.toUpperCase(),confianca_preliminar:conf.toUpperCase().replace('É','E'),justificativa_preliminar:prelim,texto_sugerido_campo_resultado:txt('sugestao'),raw:String(text||'')};
  }
  function analysisFor(h){
    const hist=manualHistory(h.id);if(hist.length){const last=hist[hist.length-1];return{source:'manual',data:parseManual(last.content||''),entry:last}}
    if(h?.ai_analysis)return{source:'auto',data:h.ai_analysis,entry:null};
    return{source:'none',data:null,entry:null};
  }
  function sourceLabel(a){return a.source==='manual'?'ChatGPT manual · resposta salva no histórico':a.source==='auto'?'IA integrada · resposta salva automaticamente':'Sem análise assistida registrada'}

  function renderGoal(){const c=bundle?.case||{};return `<div class="vosg-card"><div class="vosg-kicker">ETAPA 1 · OBJETIVO</div><h3>Qual resultado estamos tentando alcançar?</h3><div class="vosg-copy">Antes de investigar qualquer problema, precisamos manter o objetivo do cliente visível. No Método VOS, chamamos esse resultado de ${term('Destino','O resultado que o cliente quer alcançar. Não é uma ferramenta nem uma tarefa.')}</div><div class="vosg-form"><label>Resultado que o cliente quer alcançar</label><textarea id="vosg_dest" class="ym-textarea" placeholder="Ex.: receber mais clientes pelas redes sociais e gerar convites para palestras">${E(c.destination_short_term||'')}</textarea><label>Como vamos perceber que houve melhora?</label><textarea id="vosg_signal" class="ym-textarea" placeholder="Escreva sinais observáveis de melhora. Não precisa inventar uma métrica que o caso ainda não tem.">${E(c.destination_success_signal||'')}</textarea></div><div class="vosg-callout blue"><b class="vosg-copy">Regra simples</b><div class="vosg-muted">Se o objetivo for “ter Instagram”, “implantar CRM” ou “fazer anúncio”, ainda estamos falando de ferramenta. Pergunte: o que isso precisa melhorar no negócio?</div></div><div class="vosg-actions"><button class="ym-btn" onclick="vosSaveGoal()">Salvar objetivo</button><button class="ym-btn secondary" onclick="vosOpenGlossary()">Ver legenda dos termos</button></div>${nav(null,2,'Revisar o negócio')}</div>`}

  function checkSelect(code,i,val){return `<select id="vosg_q_${code}_${i}" class="ym-select"><option value="NAO_VERIFICADO" ${!val||val==='NAO_VERIFICADO'?'selected':''}>Ainda não verifiquei</option><option value="SIM" ${val==='SIM'?'selected':''}>Sim</option><option value="NAO" ${val==='NAO'?'selected':''}>Não</option></select>`}
  function renderP8(){const ps=arr(bundle?.p8_coverage);if(!ps.length)return `<div class="vosg-card"><div class="vosg-empty">Os 8Ps ainda não foram carregados para este caso.</div>${nav(1,3)}</div>`;state.p8Index=Math.min(state.p8Index,ps.length-1);const p=ps[state.p8Index],info=pInfo(p),g=(typeof P8_GUIDE!=='undefined'&&P8_GUIDE[p.p8_code])||{q:[],focus:info.what,sources:'Cliente + fontes disponíveis.'},checks=p.application_checklist||{};return `<div class="vosg-card"><div class="vosg-kicker">ETAPA 2 · REVISAR O NEGÓCIO</div><h3>Vamos revisar uma parte por vez</h3><div class="vosg-copy">Os 8Ps são apenas uma forma de não esquecer áreas importantes. Eles não dão nota e o P com pior situação não vira automaticamente a causa.</div><div class="vosg-pchips">${ps.map((x,i)=>`<button class="vosg-chip ${i===state.p8Index?'active':''} ${x.human_status==='VALIDADO'?'ok':''}" onclick="vosSelectP8(${i})">${i+1}. ${E(pInfo(x).title)} ${x.human_status==='VALIDADO'?'✓':''}</button>`).join('')}</div><div class="vosg-callout blue"><div class="vosg-kicker">AGORA ESTAMOS OLHANDO</div><h4>${E(info.title)}</h4><div class="vosg-copy">${E(info.what)}</div><div class="vosg-muted">No método: ${E(info.method)}.</div></div><div class="vosg-form"><div class="vosg-kicker">1 · RESPONDA O QUE VOCÊ REALMENTE VERIFICOU</div>${arr(g.q).map((question,i)=>`<div class="vosg-question"><span>${E(question)}</span>${checkSelect(p.p8_code,i+1,checks['q'+(i+1)])}</div>`).join('')}<label>2 · O que você percebeu aqui?</label><textarea id="vosg_obs_${p.p8_code}" class="ym-textarea" placeholder="Descreva o que está acontecendo sem dizer ainda que isso é a causa.">${E(p.observation||'')}</textarea><label>3 · O que comprova ou sustenta essa leitura? ${term('Evidência','Algo com origem identificável que sustenta uma observação. Pode ser print, link, mensagem, documento, CRM, medição ou relato registrado.')}</label><textarea id="vosg_evi_${p.p8_code}" class="ym-textarea" placeholder="Ex.: site da empresa; conversa com a cliente em 19/08; CRM; proposta comercial; print do Instagram...">${E(p.evidence_summary||'')}</textarea><details class="vosg-technical" open><summary>O que conta como evidência aqui?</summary><div class="vosg-callout amber"><div class="vosg-copy"><b>Não precisa ser sempre um print.</b> Evidência é uma informação com origem identificável. Pode ser link ou página pública, print, mensagem/WhatsApp, proposta, contrato, planilha ou CRM, métrica, documento ou um relato da cliente registrado com contexto. O relato da cliente comprova que ela declarou aquilo — não prova automaticamente que o fato acontece na prática.</div></div></details><div class="vosg-grid2"><div><label>4 · Qual é a situação desta parte?</label><select id="vosg_class_${p.p8_code}" class="ym-select"><option value="">Selecione</option>${Object.entries(CLASS_LABEL).map(([v,l])=>`<option value="${v}" ${p.classification===v?'selected':''}>${E(l)}</option>`).join('')}</select></div><div><label>5 · Quão segura está sua leitura?</label><select id="vosg_conf_${p.p8_code}" class="ym-select"><option value="">Selecione</option>${Object.entries(CONF_LABEL).map(([v,l])=>`<option value="${v}" ${p.confidence===v?'selected':''}>${E(l)}</option>`).join('')}</select></div></div><label>6 · O que ainda falta confirmar?</label><textarea id="vosg_rem_${p.p8_code}" class="ym-textarea" placeholder="Se nada relevante estiver pendente, escreva isso. Se não souber, registre o que precisa descobrir.">${E(p.remaining_validation||'')}</textarea></div><div class="vosg-actions"><button class="ym-btn" onclick="vosSaveP8('${E(p.p8_code)}')">Salvar esta parte</button>${state.p8Index>0?`<button class="ym-btn secondary" onclick="vosSelectP8(${state.p8Index-1})">← Anterior</button>`:''}${state.p8Index<ps.length-1?`<button class="ym-btn secondary" onclick="vosSelectP8(${state.p8Index+1})">Próxima →</button>`:''}</div><div class="vosg-muted" style="margin-top:8px">${p8Done()}/8 partes já validadas. Você pode salvar sem terminar tudo de uma vez.</div>${nav(1,3,'Ver o que merece investigação')}</div>`}

  function analysisPanel(h){const aa=analysisFor(h),a=aa.data;if(!a)return `<div class="vosg-callout amber"><div class="vosg-kicker">O MOTOR ENCONTROU UM PONTO QUE MERECE INVESTIGAÇÃO</div><div class="vosg-copy">${E(h.statement||'Há uma condição que precisa ser entendida melhor antes de concluir.')}</div><div class="vosg-divider"></div><div class="vosg-copy"><b>Ainda falta transformar isso em uma explicação clara.</b> Use a análise assistida para responder: o que pode estar acontecendo, por que isso pode afetar o objetivo e o que precisamos verificar na prática.</div></div><div class="vosg-actions"><button class="ym-btn" onclick="vosOpenManualAI('${E(h.id)}')">Usar ChatGPT manual</button>${typeof refreshHypAI==='function'?`<button class="ym-btn secondary" onclick="refreshHypAI('${E(h.id)}')">Analisar automaticamente</button>`:''}</div>`;
    return `<div class="vosg-callout green"><div class="vosg-kicker">O QUE PODE ESTAR ACONTECENDO</div><div class="vosg-copy"><b>${E(a.hipotese||h.statement||'')}</b></div></div><div class="vosg-grid2"><div class="vosg-callout"><div class="vosg-kicker">POR QUE ISSO PODE IMPORTAR</div><div class="vosg-copy">${E(a.por_que_importa||'')}</div></div><div class="vosg-callout"><div class="vosg-kicker">PERGUNTA QUE PRECISAMOS RESPONDER</div><div class="vosg-copy"><b>${E(a.pergunta_central||'Ainda precisamos formular a pergunta central desta investigação.')}</b></div></div></div><div class="vosg-grid2"><div class="vosg-callout blue"><h4>O que já sabemos</h4>${listHtml(a.evidencias_ja_existentes)}</div><div class="vosg-callout amber"><h4>O que ainda precisamos descobrir</h4>${listHtml(a.o_que_falta_descobrir)}</div></div><div class="vosg-callout"><div class="vosg-kicker">COMO INVESTIGAR NA PRÁTICA</div>${listHtml(a.como_validar)}</div><div class="vosg-status"><span>Origem: ${E(sourceLabel(aa))}</span>${a.resultado_preliminar?`<span class="warn">Leitura preliminar: ${E(RESULT_LABEL[a.resultado_preliminar]||q(a.resultado_preliminar))}</span>`:''}${a.confianca_preliminar?`<span>Confiança da leitura: ${E(q(a.confianca_preliminar))}</span>`:''}</div><div class="vosg-callout blue"><div class="vosg-copy"><b>Importante:</b> esta análise da IA não é evidência e não decide a hipótese. Ela organiza o raciocínio e diz onde olhar. A evidência vem do que você verificar no caso.</div></div><div class="vosg-actions"><button class="ym-btn secondary" onclick="vosOpenManualAI('${E(h.id)}')">Gerar novo prompt / registrar nova leitura</button>${typeof refreshHypAI==='function'?`<button class="ym-btn secondary" onclick="refreshHypAI('${E(h.id)}')">Atualizar IA automática</button>`:''}</div>`}
  function historyHtml(h){const hist=manualHistory(h.id);if(!hist.length&&!h.ai_analysis)return'';return `<div class="vosg-history"><details><summary>Histórico da análise assistida (${hist.length+(h.ai_analysis?1:0)} registro${hist.length+(h.ai_analysis?1:0)===1?'':'s'})</summary>${h.ai_analysis?`<div class="vosg-callout blue"><b class="vosg-copy">IA automática</b><div class="vosg-muted">Gerada ${E(h.ai_generated_at?YM.datePt(h.ai_generated_at):'automaticamente')}.</div></div>`:''}${hist.map(e=>{const stamp=String(e.source_ref||'').split('/').slice(2).join('/');let d=stamp;try{d=new Date(stamp).toLocaleString('pt-BR')}catch{}return `<details style="margin-top:7px"><summary>ChatGPT manual · ${E(d)}</summary><pre>${E(e.content||'')}</pre></details>`}).join('')}</details></div>`}
  function renderHypotheses(){const hs=arr(bundle?.hypotheses);if(!hs.length)return `<div class="vosg-card"><div class="vosg-kicker">ETAPA 3 · ENTENDER O QUE INVESTIGAR</div><h3>Ainda não há uma possível explicação registrada</h3><div class="vosg-copy">O MOTOR só deve criar explicações depois que a revisão do negócio estiver completa e houver algo que realmente mereça investigação.</div><div class="vosg-callout amber"><div class="vosg-copy">Se os 8Ps já estiverem validados e houver um ponto classificado como “merece investigação”, atualize o caso para o MOTOR gerar as candidatas.</div></div><div class="vosg-actions"><button class="ym-btn" onclick="openCase(currentId)">Atualizar caso</button></div>${nav(2,4)}</div>`;state.hypIndex=Math.min(state.hypIndex,hs.length-1);const h=hs[state.hypIndex],info=pInfo({p8_code:h.p8_code,p8_label:h.p8_code});return `<div class="vosg-card"><div class="vosg-kicker">ETAPA 3 · ENTENDER O QUE INVESTIGAR</div><h3>Vamos entender uma possível explicação por vez</h3><div class="vosg-copy">${term('Possível explicação','No método, é a hipótese. É algo que pode explicar parte da distância até o objetivo, mas ainda precisa ser verificado.')} não é conclusão. Aqui o MOTOR precisa dizer com clareza <b>o que pode estar acontecendo</b> e <b>o que você deve verificar.</b></div><div class="vosg-hchips">${hs.map((x,i)=>`<button class="vosg-chip ${i===state.hypIndex?'active':''} ${FINAL_HYP.has(x.status)?'ok':''}" onclick="vosSelectHyp(${i})">${i+1}. ${E(pInfo({p8_code:x.p8_code,p8_label:x.p8_code}).title)} ${FINAL_HYP.has(x.status)?'✓':''}</button>`).join('')}</div><div class="vosg-muted">Origem metodológica: ${E(info.method)} · status técnico ${E(q(h.status))}. Esses termos ficam em segundo plano; o foco é entender o caso.</div>${analysisPanel(h)}${historyHtml(h)}<details class="vosg-technical"><summary>Ver registro técnico original</summary><div class="vosg-callout"><div class="vosg-muted">Hipótese registrada no banco:</div><div class="vosg-copy">${E(h.statement||'')}</div>${arr(h.tests).length?`<div class="vosg-muted" style="margin-top:7px">Teste técnico: ${E(h.tests[0].test_description||'')}</div>`:''}</div></details>${nav(2,4,'Começar a investigação')}</div>`}

  function draftKey(hid){return `vos-guided-invest:${currentId}:${hid}`}
  function getDraft(hid){try{return JSON.parse(localStorage.getItem(draftKey(hid))||'{}')||{}}catch{return{}}}
  function setDraft(hid,patch){const d={...getDraft(hid),...patch};try{localStorage.setItem(draftKey(hid),JSON.stringify(d))}catch{}return d}
  function renderInvestigation(){const hs=arr(bundle?.hypotheses);if(!hs.length)return `<div class="vosg-card"><div class="vosg-empty">Ainda não há investigação para realizar.</div>${nav(3,5)}</div>`;state.investIndex=Math.min(state.investIndex,hs.length-1);const h=hs[state.investIndex],aa=analysisFor(h),a=aa.data||{},steps=arr(a.como_validar),t=arr(h.tests).find(x=>!x.result_classification)||arr(h.tests)[0]||null,d=getDraft(h.id),notes=arr(d.notes);const final=FINAL_HYP.has(h.status);return `<div class="vosg-card"><div class="vosg-kicker">ETAPA 4 · REGISTRAR O QUE ENCONTRAMOS</div><h3>Agora faça a investigação — passo a passo</h3><div class="vosg-hchips">${hs.map((x,i)=>`<button class="vosg-chip ${i===state.investIndex?'active':''} ${FINAL_HYP.has(x.status)?'ok':''}" onclick="vosSelectInvest(${i})">${i+1}. ${E(pInfo({p8_code:x.p8_code,p8_label:x.p8_code}).title)} ${FINAL_HYP.has(x.status)?'✓':''}</button>`).join('')}</div><div class="vosg-callout green"><div class="vosg-kicker">O QUE ESTAMOS TENTANDO DESCOBRIR</div><div class="vosg-copy"><b>${E(a.pergunta_central||a.hipotese||h.statement||'Precisamos verificar se esta possível explicação realmente tem relação com o objetivo.')}</b></div></div>${!aa.data?`<div class="vosg-callout amber"><div class="vosg-copy">Antes de testar, gere a análise assistida na etapa anterior. Ela transforma o teste técnico em passos concretos: onde olhar, o que procurar e como interpretar.</div><button class="ym-btn secondary" style="margin-top:8px" onclick="vosGoStep(3)">Voltar e gerar análise</button></div>`:''}${steps.length?steps.map((s,i)=>`<div class="vosg-invest-step"><div><span class="num">${i+1}</span><b class="vosg-copy">${E(s)}</b></div><label class="ym-label">O que você encontrou neste passo?</label><textarea class="ym-textarea" placeholder="Registre somente o que você realmente verificou. Se não conseguiu verificar, escreva isso." oninput="vosSaveInvestNote('${E(h.id)}',${i},this.value)">${E(notes[i]||'')}</textarea></div>`).join(''):`<div class="vosg-callout amber"><div class="vosg-copy">O roteiro prático ainda não foi gerado. Use a análise assistida antes de registrar o resultado.</div></div>`}${t?.result_classification?`<div class="vosg-callout green"><div class="vosg-kicker">RESULTADO DO TESTE JÁ REGISTRADO</div><div class="vosg-copy"><b>${E(RESULT_LABEL[t.result_classification]||q(t.result_classification))}</b></div><div class="vosg-copy" style="margin-top:6px">${E(t.result_summary||'')}</div></div>`:''}${!t?`<div class="vosg-callout amber"><div class="vosg-copy">Não existe ainda um registro técnico de teste para esta possível explicação.</div><button class="ym-btn secondary" style="margin-top:8px" onclick="vosCreateGuidedTest('${E(h.id)}')">Preparar registro da investigação</button></div>`:''}${t&&!t.result_classification?`<div class="vosg-divider"></div><h4>O que os dados indicam?</h4><div class="vosg-copy">Escolha com base no que você verificou — não no que você esperava encontrar.</div><div class="vosg-choice"><label><input type="radio" name="vosg_result_${E(h.id)}" value="SUPORTA" ${d.result==='SUPORTA'?'checked':''} onchange="vosSaveInvestResult('${E(h.id)}',this.value)"><div><b>🟢 Há sinais que sustentam esta explicação</b><span>Encontramos informações que mostram que ela pode estar contribuindo para o objetivo não avançar.</span></div></label><label><input type="radio" name="vosg_result_${E(h.id)}" value="CONTRADIZ" ${d.result==='CONTRADIZ'?'checked':''} onchange="vosSaveInvestResult('${E(h.id)}',this.value)"><div><b>🔴 Os dados apontam contra esta explicação</b><span>O que encontramos não combina com a explicação ou mostra que esse ponto funciona adequadamente.</span></div></label><label><input type="radio" name="vosg_result_${E(h.id)}" value="INCONCLUSIVO" ${d.result==='INCONCLUSIVO'?'checked':''} onchange="vosSaveInvestResult('${E(h.id)}',this.value)"><div><b>🟡 Ainda não conseguimos saber</b><span>Faltam dados ou não foi possível verificar o suficiente. Isso é um resultado válido.</span></div></label></div><div class="vosg-form"><label>Resumo do que você encontrou</label><textarea id="vosg_test_summary_${E(h.id)}" class="ym-textarea" placeholder="O MOTOR pode montar esse resumo a partir das suas anotações, mas revise antes de registrar.">${E(d.summary||'')}</textarea></div><div class="vosg-actions"><button class="ym-btn" onclick="vosCompleteTest('${E(h.id)}','${E(t.id)}')">Registrar resultado da investigação</button></div>`:''}${t?.result_classification&&!final?`<div class="vosg-divider"></div><h4>Depois do teste, o que você conclui sobre esta possível explicação?</h4><div class="vosg-form"><select id="vosg_hdec_${E(h.id)}" class="ym-select"><option value="VALIDADA">Os dados sustentam esta explicação</option><option value="REJEITADA">Os dados apontam contra esta explicação</option><option value="INCONCLUSIVA">Ainda não dá para decidir</option></select><label>Quão segura está essa decisão?</label><select id="vosg_hconf_${E(h.id)}" class="ym-select">${Object.entries(CONF_LABEL).filter(([v])=>v!=='SEM_BASE').map(([v,l])=>`<option value="${v}" ${h.confidence===v?'selected':''}>${E(l)}</option>`).join('')}</select><label>Por quê?</label><textarea id="vosg_hrat_${E(h.id)}" class="ym-textarea">${E(t.result_summary||'')}</textarea></div><div class="vosg-actions"><button class="ym-btn" onclick="vosDecideHyp('${E(h.id)}')">Salvar conclusão desta explicação</button></div>`:''}${final?`<div class="vosg-callout green"><div class="vosg-copy"><b>Esta possível explicação já foi encerrada:</b> ${E(q(h.status))}. Confiança ${E(q(h.confidence||'não informada'))}.</div></div>`:''}${nav(3,5,'Ir para a conclusão')}</div>`}

  function renderConclusion(){const c=bundle?.case||{},hs=arr(bundle?.hypotheses),cs=arr(bundle?.conclusions),g=gate(),valid=p8Done(),pending=hypPending(),ready=valid===8&&pending===0&&cs.length>0;return `<div class="vosg-card"><div class="vosg-kicker">ETAPA 5 · CONCLUIR O VER</div><h3>O que os dados permitem concluir?</h3><div class="vosg-copy">Agora juntamos o que foi verificado. Aqui não é hora de criar uma nova hipótese: é hora de registrar até onde conseguimos chegar com segurança.</div><div class="vosg-callout blue"><div class="vosg-kicker">OBJETIVO DO CASO</div><div class="vosg-copy"><b>${E(c.destination_short_term||'Objetivo não registrado')}</b></div></div><div class="vosg-status"><span class="${valid===8?'ok':'warn'}">${valid}/8 partes revisadas</span><span class="${pending===0?'ok':'warn'}">${hs.length-pending}/${hs.length} explicações encerradas</span><span class="${cs.length?'ok':'warn'}">${cs.length} conclusão(ões) registrada(s)</span></div>${hs.length?`<div class="vosg-callout"><h4>Resultado das possíveis explicações</h4>${listHtml(hs.map((h,i)=>`${i+1}. ${pInfo({p8_code:h.p8_code,p8_label:h.p8_code}).title}: ${q(h.status)}${h.confidence?' · confiança '+q(h.confidence):''}`))}</div>`:''}${cs.length?`<div class="vosg-callout green"><h4>Conclusões já registradas</h4>${listHtml(cs.map(x=>x.statement||x.content||'Conclusão registrada'))}</div>`:`<div class="vosg-form"><label>Qual é a conclusão principal?</label><textarea id="vosg_conclusion" class="ym-textarea" placeholder="Escreva o que os dados permitem afirmar agora, sem ir além do que foi verificado."></textarea><div class="vosg-grid2"><div><label>Que tipo de conclusão é esta?</label><select id="vosg_ctype" class="ym-select"><option value="CAUSA_PROVAVEL">Causa provável — há bons sinais, mas não prova definitiva</option><option value="CAUSA_VALIDADA">Causa validada — há evidência suficiente para afirmar</option><option value="OUTRA">Conclusão geral / combinação de fatores</option></select></div><div><label>Quão segura está essa conclusão?</label><select id="vosg_cconf" class="ym-select">${Object.entries(CONF_LABEL).filter(([v])=>v!=='SEM_BASE').map(([v,l])=>`<option value="${v}">${E(l)}</option>`).join('')}</select></div></div><label>Por que você chegou a essa conclusão?</label><textarea id="vosg_crat" class="ym-textarea" placeholder="Resuma as evidências e resultados dos testes que sustentam a conclusão."></textarea><label>O que ainda não sabemos?</label><textarea id="vosg_cunc" class="ym-textarea" placeholder="Se houver incerteza ou informação faltante, deixe registrado."></textarea><div class="vosg-actions"><button class="ym-btn" ${readyConclusion()?'':'disabled'} onclick="vosAddConclusion()">Registrar conclusão</button></div>${!readyConclusion()?`<div class="vosg-muted">Antes de concluir, termine a revisão dos 8Ps e encerre as possíveis explicações pendentes.</div>`:''}</div>`}<div class="vosg-divider"></div><h4>Temos informação suficiente para encerrar o VER?</h4><div class="vosg-copy">No método, este ponto de controle é chamado de ${term('Gate','Ponto de controle que pergunta se já existe informação suficiente para encerrar o VER e começar a ordenar ações.')}.</div>${g.status==='APROVADO'?`<div class="vosg-callout green"><div class="vosg-copy"><b>VER encerrado.</b> Já existe informação suficiente registrada para seguir ao ORDENAR.</div></div>`:`<div class="vosg-form"><label>Por que já podemos encerrar esta investigação?</label><textarea id="vosg_gate_reason" class="ym-textarea" placeholder="Explique por que as informações atuais são suficientes para seguir."></textarea><label>Existe alguma ressalva que precisa continuar registrada?</label><textarea id="vosg_gate_remaining" class="ym-textarea" placeholder="Ex.: preço ainda será validado com a cliente, mas isso não impede a conclusão atual."></textarea><div class="vosg-actions"><button class="ym-btn" ${ready?'':'disabled'} onclick="vosCloseVer()">Encerrar VER e liberar ORDENAR</button></div>${!ready?`<div class="vosg-callout amber"><div class="vosg-copy"><b>Ainda não dá para encerrar.</b> ${valid<8?`Faltam ${8-valid} parte(s) dos 8Ps. `:''}${pending?`Faltam ${pending} possível(is) explicação(ões). `:''}${!cs.length?'Falta registrar pelo menos uma conclusão humana.':''}</div></div>`:''}`}${nav(4,6,'Ir para Ordenar')}</div>`}

  function renderOrder(){const g=gate(),items=arr(bundle?.order_candidates);if(g.status!=='APROVADO')return `<div class="vosg-card"><div class="vosg-kicker">ETAPA 6 · ORDENAR</div><h3>Ainda não é hora de ordenar ações</h3><div class="vosg-copy">Primeiro precisamos encerrar o VER. Isso evita escolher solução antes de entender o que realmente merece ser tratado.</div>${nav(5,null)}</div>`;return `<div class="vosg-card"><div class="vosg-kicker">ETAPA 6 · ORDENAR</div><h3>Agora sim: o que deve acontecer primeiro?</h3><div class="vosg-copy">As ações aparecem como candidatas. A ordem final continua humana: escolha com base no impacto no objetivo e nas dependências entre ações.</div>${items.length?items.slice().sort((a,b)=>(a.sequence_order||999)-(b.sequence_order||999)).map(o=>`<div class="vosg-order"><div>${o.human_status==='VALIDADO'&&!o.not_now?`<div class="seq">${E(o.sequence_order)}</div>`:`<span class="vosg-chip">${o.not_now?'Não agora':E(q(o.human_status||'Pendente'))}</span>`}</div><div><h4>${E(o.action)}</h4><div class="vosg-copy">${E(o.rationale||'')}</div>${o.human_status==='PENDENTE'?`<div class="vosg-grid2 vosg-form"><div><label>Ordem</label><input id="os_${E(o.id)}" type="number" min="1" class="ym-input"></div><div><label>Por que nesta ordem?</label><input id="or_${E(o.id)}" class="ym-input"></div></div><div class="vosg-actions"><button class="ym-btn" onclick="vosValidateOrder('${E(o.id)}',${Boolean(o.not_now)})">Confirmar</button><button class="ym-btn secondary" onclick="vosRejectOrder('${E(o.id)}')">Descartar</button></div>`:''}</div></div>`).join(''):'<div class="vosg-empty">Ainda não existem ações candidatas.</div>'}<div class="vosg-divider"></div><h4>Adicionar uma ação candidata</h4><div class="vosg-form"><label>O que precisa ser feito?</label><textarea id="vosg_oa" class="ym-textarea"></textarea><label>Por que isso pode ajudar?</label><textarea id="vosg_or" class="ym-textarea"></textarea><label>Como isso se conecta ao objetivo?</label><textarea id="vosg_oi" class="ym-textarea"></textarea><label style="display:flex;gap:7px;align-items:center;font-family:Inter;font-weight:500"><input id="vosg_on" type="checkbox"> Não é para agora</label></div><div class="vosg-actions"><button class="ym-btn" onclick="vosCreateOrder()">Adicionar ação</button></div>${nav(5,null)}</div>`}

  function renderGuided(){if(!bundle||!currentId)return;restore();const c=bundle.case||{};const w=document.getElementById('workspace');if(!w)return;const title=document.querySelector('.ym-title'),lead=document.querySelector('.ym-lead');if(title)title.textContent='MOTOR VOS — aplicação guiada';if(lead)lead.textContent='Uma etapa por vez: entender, investigar, concluir e só então ordenar ações.';const body=[renderGoal,renderP8,renderHypotheses,renderInvestigation,renderConclusion,renderOrder][state.step-1]();w.innerHTML=`<div class="vosg-wrap"><div class="vosg-hero"><div class="vosg-eyebrow">MÉTODO VOS · MODO GUIADO</div><h2>${E(c.business_name||c.client_ref||'Caso VOS')}</h2><p>${E(c.client_name||'')} ${c.status?'· '+E(q(c.status)):''}</p><div style="margin-top:7px"><button class="vosg-glossary-btn" onclick="vosOpenGlossary()">Não entendeu algum termo? Abrir legenda simples</button></div>${stepBar()}</div>${body}</div>`;remember()}

  function currentP8Rows(activeCode){return arr(bundle?.p8_coverage).map(p=>{const active=p.p8_code===activeCode,checks={...(p.application_checklist||{})};if(active){for(let i=1;i<=4;i++)checks['q'+i]=document.getElementById(`vosg_q_${activeCode}_${i}`)?.value||'NAO_VERIFICADO'}return{p8_code:p.p8_code,observation:active?(document.getElementById('vosg_obs_'+activeCode)?.value||''):(p.observation||''),evidence_summary:active?(document.getElementById('vosg_evi_'+activeCode)?.value||''):(p.evidence_summary||''),classification:active?(document.getElementById('vosg_class_'+activeCode)?.value||null):(p.classification||null),confidence:active?(document.getElementById('vosg_conf_'+activeCode)?.value||null):(p.confidence||null),remaining_validation:active?(document.getElementById('vosg_rem_'+activeCode)?.value||''):(p.remaining_validation||''),application_checklist:checks}})}

  window.vosGoStep=n=>{state.step=Math.max(1,Math.min(6,Number(n)||1));remember();renderGuided();window.scrollTo({top:0,behavior:'smooth'})};
  window.vosSelectP8=i=>{state.p8Index=Math.max(0,Number(i)||0);remember();renderGuided()};
  window.vosSelectHyp=i=>{state.hypIndex=Math.max(0,Number(i)||0);remember();renderGuided()};
  window.vosSelectInvest=i=>{state.investIndex=Math.max(0,Number(i)||0);remember();renderGuided()};

  window.vosSaveGoal=async()=>{try{await authFetch('motor-ver-actions','POST',{action:'UPDATE_DESTINATION',case_id:currentId,destination_short_term:document.getElementById('vosg_dest')?.value||'',destination_success_signal:document.getElementById('vosg_signal')?.value||''});YM.toast('Objetivo salvo.');state.step=2;remember();await openCase(currentId)}catch(e){YM.toast(e.message||String(e),true)}};
  window.vosSaveP8=async code=>{try{const rows=currentP8Rows(code);await authFetch('motor-save-ver-guided','POST',{case_id:currentId,destination_short_term:bundle?.case?.destination_short_term||'',destination_success_signal:bundle?.case?.destination_success_signal||'',p8:rows});YM.toast('Parte salva. O que não foi verificado continua registrado como pendente.');await openCase(currentId)}catch(e){YM.toast(e.message||String(e),true)}};

  function buildContext(hid){const b=bundle||{},c=b.case||{},selected=arr(b.hypotheses).find(h=>h.id===hid);if(!selected)throw new Error('Possível explicação não encontrada.');const pickEntry=e=>({p8_code:e?.p8_code||'',tipo:e?.ver_field||e?.evidence_type||e?.conclusion_type||'',title:e?.title||'',statement:e?.statement||'',content:e?.content||'',classification:e?.classification||'',confidence:e?.confidence||'',human_status:e?.human_status||'',reliability:e?.reliability||'',source_type:e?.source_type||'',source_ref:e?.source_ref||''});const pickHyp=h=>({id:h?.id||'',p8_code:h?.p8_code||'',statement:h?.statement||'',status:h?.status||'',confidence:h?.confidence||'',tests:arr(h?.tests).map(t=>({id:t?.id||'',test_description:t?.test_description||'',method:t?.method||'',expected_evidence:t?.expected_evidence||'',result_summary:t?.result_summary||'',result_classification:t?.result_classification||''}))});return{caso:{business_name:c.business_name||c.client_ref||'',client_name:c.client_name||'',status:c.status||'',destination_short_term:c.destination_short_term||'',destination_success_signal:c.destination_success_signal||''},cobertura_8ps:arr(b.p8_coverage),mapa_ver:arr(b.ver_entries).map(pickEntry),evidencias:arr(b.evidence).map(pickEntry),hipotese_em_analise:pickHyp(selected),outras_hipoteses:arr(b.hypotheses).filter(h=>h.id!==hid).map(h=>({p8_code:h.p8_code||'',statement:h.statement||'',status:h.status||'',confidence:h.confidence||''})),conclusoes_humanas_existentes:arr(b.conclusions).map(pickEntry)}}
  function buildPrompt(hid){const ctx=buildContext(hid);return `Você está atuando como CAMADA DE ANÁLISE ASSISTIDA do MOTOR VOS da YM Marketing & Negócios.\n\nSeu papel é AJUDAR O APLICADOR HUMANO A PENSAR sobre uma hipótese causal já registrada. Você recebe abaixo o Destino, cobertura humana dos 8Ps, mapa VER, evidências, hipótese selecionada, testes e demais informações disponíveis no caso.\n\nREGRAS INVIOLÁVEIS\n1. Você NÃO valida causa, NÃO aprova hipótese, NÃO aprova Gate e NÃO prioriza ORDENAR. A decisão final é humana.\n2. Não trate DISFUNÇÃO como causa. Disfunção é uma condição observada que pode ou não contribuir para o destino.\n3. LACUNA e INCONCLUSIVO são limites de informação, nunca defeitos automáticos.\n4. Use SOMENTE os dados fornecidos. Não invente métricas, comportamento de clientes, perdas, conversões, fatos externos ou evidências que não estejam no caso.\n5. Diferencie claramente EVIDÊNCIA, HIPÓTESE, INFERÊNCIA e DADO AINDA DESCONHECIDO.\n6. Os 8Ps são cobertura de análise; NÃO são score e a menor classificação não deve ser transformada automaticamente em causa.\n7. A investigação busca identificar a causa predominante ou o conjunto de fatores causais prioritários que pode estar impedindo o avanço ao Destino.\n8. Se não houver base suficiente, diga INCONCLUSIVO. “Não sei” e “não verificado” significam que falta informação.\n9. Linguagem em português simples, direta, consultiva e operacional. Evite jargão desnecessário.\n10. Não recomende produto ou serviço da YM nesta etapa. O objetivo é investigação.\n11. Considere a hipótese selecionada dentro do contexto do caso inteiro e verifique se outras informações a sustentam, contradizem ou mostram que ainda é cedo para concluir.\n12. A resposta precisa orientar um aplicador iniciante: diga onde olhar, o que fazer, o que registrar e como interpretar o que encontrar.\n\nENTREGUE A RESPOSTA NESTA ESTRUTURA\n\nO QUE A IA ESTÁ VENDO\nExplique em 2 a 4 parágrafos curtos o que os dados realmente mostram e conecte a leitura ao Destino.\n\nHIPÓTESE QUE VALE INVESTIGAR\nReescreva a hipótese de forma específica, concreta e compreensível, sem afirmá-la como verdade.\n\nPOR QUE ISSO PODE IMPORTAR\nExplique como a hipótese PODE afetar o Destino, sem afirmar causalidade não provada.\n\nO QUE JÁ TEMOS DE EVIDÊNCIA\nListe somente evidências existentes nos dados fornecidos.\n\nO QUE AINDA PRECISAMOS DESCOBRIR\nListe dados, perguntas ou evidências que ainda faltam para decidir.\n\nA PERGUNTA QUE O TESTE PRECISA RESPONDER\nCrie uma pergunta objetiva que permita testar a hipótese.\n\nCOMO VALIDAR NA PRÁTICA\nDê passos simples e executáveis. Para cada passo, deixe claro ONDE OLHAR, O QUE FAZER, O QUE REGISTRAR e, quando possível, COMO INTERPRETAR o resultado. Use apenas fontes compatíveis com o caso: cliente, canais, CRM, documentos, mensagens, medição ou outras já disponíveis.\n\nLEITURA PRELIMINAR DA IA\nEscolha somente: SUPORTA, CONTRADIZ ou INCONCLUSIVO. Informe também confiança ALTA, MEDIA ou BAIXA e justifique. Isso é apenas leitura assistida, não decisão humana.\n\nSUGESTÃO PARA O CAMPO “O QUE VOCÊ ENCONTROU?”\nEscreva um texto pronto, em primeira pessoa do aplicador, que separe o que os dados já mostram do que ainda depende de validação.\n\nDADOS DO CASO MOTOR VOS\n${JSON.stringify(ctx,null,2)}\n\nAntes de responder, verifique se alguma conclusão está indo além das evidências. Se estiver, rebaixe para hipótese ou INCONCLUSIVO.`}

  function closeModal(){document.getElementById('vosgModal')?.remove()}
  window.vosOpenGlossary=()=>{closeModal();const wrap=document.createElement('div');wrap.id='vosgModal';wrap.className='vosg-modal';wrap.innerHTML=`<div class="vosg-modal-card"><div class="vosg-modal-head"><div><b>LEGENDA SIMPLES DO MOTOR</b><p>Os termos do método ficam disponíveis, mas você não precisa decorá-los para aplicar.</p></div><button class="vosg-close" onclick="document.getElementById('vosgModal').remove()">×</button></div><div class="vosg-modal-body"><div class="vosg-gloss"><div><b>Destino</b><p>O resultado que o cliente quer alcançar. Ex.: receber mais clientes pelas redes. Não é a ferramenta usada.</p></div><div><b>8Ps</b><p>Checklist de áreas do negócio para garantir cobertura. Não é score e não aponta a causa automaticamente.</p></div><div><b>Evidência</b><p>Algo com origem identificável que sustenta uma observação: link, print, mensagem, documento, CRM/planilha, métrica, proposta, contrato ou relato da cliente registrado com contexto. A resposta da IA não é evidência.</p></div><div><b>Possível explicação (Hipótese)</b><p>Algo que pode explicar parte da distância até o Destino. Ainda precisa ser investigado.</p></div><div><b>Investigação / Teste</b><p>Passos concretos para descobrir se a possível explicação combina ou não com o que acontece no caso.</p></div><div><b>Inconclusivo</b><p>Não existe informação suficiente para decidir. Não é erro e não significa que o negócio tem um problema.</p></div><div><b>Gate</b><p>Ponto de controle interno: temos informação suficiente para encerrar o VER e começar a ordenar ações?</p></div><div><b>Ordenar</b><p>Escolher o que deve ser tratado primeiro, em qual sequência e por quê.</p></div></div></div></div>`;document.body.appendChild(wrap);wrap.addEventListener('click',e=>{if(e.target===wrap)closeModal()})};

  window.vosOpenManualAI=hid=>{try{closeModal();const prompt=buildPrompt(hid),draft=localStorage.getItem('vosg-ai-draft:'+currentId+':'+hid)||'';const wrap=document.createElement('div');wrap.id='vosgModal';wrap.className='vosg-modal';wrap.innerHTML=`<div class="vosg-modal-card"><div class="vosg-modal-head"><div><b>ANÁLISE ASSISTIDA · MODO MANUAL</b><p>1) copie o prompt; 2) cole no ChatGPT; 3) volte aqui; 4) cole e salve a resposta.</p></div><button class="vosg-close" onclick="document.getElementById('vosgModal').remove()">×</button></div><div class="vosg-modal-body"><div class="vosg-callout blue"><div class="vosg-copy"><b>Por que salvar a resposta?</b> Para que a linha de raciocínio usada fique registrada no caso e possa ser auditada no futuro. A resposta da IA é apoio à análise — não é evidência do negócio.</div></div><label class="ym-label">1 · Prompt para o ChatGPT</label><textarea id="vosg_manual_prompt" class="ym-textarea vosg-prompt" readonly></textarea><div class="vosg-actions"><button id="vosg_copy_prompt" class="ym-btn">Copiar prompt</button></div><div class="vosg-divider"></div><label class="ym-label">2 · Cole aqui a resposta completa do ChatGPT</label><textarea id="vosg_manual_response" class="ym-textarea" placeholder="Cole a resposta completa, mantendo os títulos da análise." oninput="localStorage.setItem('vosg-ai-draft:${E(currentId)}:${E(hid)}',this.value)">${E(draft)}</textarea><div class="vosg-actions"><button class="ym-btn" onclick="vosSaveManualAI('${E(hid)}')">Salvar resposta no histórico do caso</button><button class="ym-btn secondary" onclick="document.getElementById('vosgModal').remove()">Fechar sem salvar</button></div></div></div>`;document.body.appendChild(wrap);document.getElementById('vosg_manual_prompt').value=prompt;document.getElementById('vosg_copy_prompt').onclick=async()=>{const ta=document.getElementById('vosg_manual_prompt');try{await navigator.clipboard.writeText(prompt);YM.toast('Prompt copiado. Cole no ChatGPT.')}catch{ta.focus();ta.select();document.execCommand('copy');YM.toast('Prompt copiado. Cole no ChatGPT.')}};wrap.addEventListener('click',e=>{if(e.target===wrap)closeModal()})}catch(e){YM.toast(e.message||String(e),true)}};
  window.generateChatGPTPrompt=window.vosOpenManualAI;
  window.vosSaveManualAI=async hid=>{const text=document.getElementById('vosg_manual_response')?.value?.trim();if(!text)return YM.toast('Cole a resposta do ChatGPT antes de salvar.',true);try{const h=arr(bundle?.hypotheses).find(x=>x.id===hid);await authFetch('motor-ver-actions','POST',{action:'ADD_VER_ENTRY',case_id:currentId,ver_field:'CONTEXTO',title:'Análise assistida · ChatGPT manual',content:text,p8_code:h?.p8_code||null,source_type:'AI_SUGGESTION',source_ref:`CHATGPT_MANUAL/${hid}/${new Date().toISOString()}`});localStorage.removeItem('vosg-ai-draft:'+currentId+':'+hid);closeModal();YM.toast('Resposta salva no histórico do caso.');state.step=3;remember();await openCase(currentId)}catch(e){YM.toast(e.message||String(e),true)}};

  window.vosSaveInvestNote=(hid,i,v)=>{const d=getDraft(hid),notes=arr(d.notes);notes[i]=v;setDraft(hid,{notes})};
  window.vosSaveInvestResult=(hid,v)=>setDraft(hid,{result:v});
  window.vosCreateGuidedTest=async hid=>{const h=arr(bundle?.hypotheses).find(x=>x.id===hid),a=analysisFor(h).data||{};try{await authFetch('motor-ver-actions','POST',{action:'ADD_HYPOTHESIS_TEST',case_id:currentId,hypothesis_id:hid,test_description:a.pergunta_central||'Verificar se esta possível explicação tem relação com o Destino.',method:arr(a.como_validar).join(' | ')||'Seguir o roteiro de investigação assistida.',expected_evidence:'Registrar somente informações verificadas no caso e sua origem.'});YM.toast('Roteiro de investigação preparado.');await openCase(currentId)}catch(e){YM.toast(e.message||String(e),true)}};
  window.vosCompleteTest=async(hid,tid)=>{const d=getDraft(hid),result=d.result||document.querySelector(`input[name="vosg_result_${hid}"]:checked`)?.value;let summary=document.getElementById('vosg_test_summary_'+hid)?.value?.trim()||d.summary||'';if(!summary){summary=arr(d.notes).map((x,i)=>x?.trim()?`Passo ${i+1}: ${x.trim()}`:'').filter(Boolean).join('\n')}if(!result)return YM.toast('Escolha o que os dados indicam.',true);if(!summary)return YM.toast('Registre o que você encontrou antes de concluir o teste.',true);setDraft(hid,{result,summary});try{await authFetch('motor-ver-investigation','POST',{action:'COMPLETE_TEST',case_id:currentId,test_id:tid,result_classification:result,result_summary:summary});YM.toast('Resultado da investigação registrado.');await openCase(currentId)}catch(e){YM.toast(e.message||String(e),true)}};
  window.vosDecideHyp=async hid=>{const status=document.getElementById('vosg_hdec_'+hid)?.value,confidence=document.getElementById('vosg_hconf_'+hid)?.value,rationale=document.getElementById('vosg_hrat_'+hid)?.value?.trim();if(!rationale)return YM.toast('Explique por que você chegou a essa decisão.',true);try{await authFetch('motor-ver-actions','POST',{action:'VALIDATE_HYPOTHESIS',case_id:currentId,hypothesis_id:hid,status,confidence,rationale});YM.toast('Possível explicação encerrada.');try{localStorage.removeItem(draftKey(hid))}catch{}await openCase(currentId)}catch(e){YM.toast(e.message||String(e),true)}};

  window.vosAddConclusion=async()=>{const statement=document.getElementById('vosg_conclusion')?.value?.trim(),conclusion_type=document.getElementById('vosg_ctype')?.value,confidence=document.getElementById('vosg_cconf')?.value,rationale=document.getElementById('vosg_crat')?.value?.trim(),uncertainty=document.getElementById('vosg_cunc')?.value?.trim();if(!statement||!rationale)return YM.toast('Registre a conclusão e por que você chegou a ela.',true);try{await authFetch('motor-ver-actions','POST',{action:'ADD_CONCLUSION',case_id:currentId,statement,conclusion_type,confidence,rationale,uncertainty,impact_on_destination:bundle?.case?.destination_short_term||''});YM.toast('Conclusão registrada.');await openCase(currentId)}catch(e){YM.toast(e.message||String(e),true)}};
  window.vosCloseVer=async()=>{const justification=document.getElementById('vosg_gate_reason')?.value?.trim(),remaining_conditions=document.getElementById('vosg_gate_remaining')?.value?.trim();if(!justification)return YM.toast('Explique por que já existe informação suficiente para encerrar o VER.',true);try{await authFetch('motor-ver-investigation','POST',{action:'SET_GATE_SAFE',case_id:currentId,status:'APROVADO',justification,remaining_conditions});YM.toast('VER encerrado. ORDENAR liberado.');state.step=6;remember();await openCase(currentId);await loadDashboard()}catch(e){const m={hypotheses_still_pending:'Ainda existem possíveis explicações sem decisão.',human_conclusion_required:'Registre a conclusão antes de encerrar o VER.',causal_hypothesis_required_for_dysfunction:'Existe um ponto que merece investigação e ainda não foi tratado.',all_8p_must_be_human_validated:'Termine a revisão das 8 partes antes de encerrar.'};YM.toast(m[e.message]||e.message||String(e),true)}};

  window.vosValidateOrder=async(id,notNow)=>{const sequence=notNow?null:Number(document.getElementById('os_'+id)?.value),rationale=document.getElementById('or_'+id)?.value?.trim();if(!notNow&&(!sequence||sequence<1))return YM.toast('Informe a ordem desta ação.',true);if(!rationale)return YM.toast('Explique por que esta ação fica nesta ordem.',true);try{await authFetch('motor-order-actions','POST',{action:'VALIDATE_CANDIDATE',case_id:currentId,candidate_id:id,sequence_order:sequence,validation_rationale:rationale});YM.toast('Ação ordenada.');await openCase(currentId)}catch(e){YM.toast(e.message||String(e),true)}};
  window.vosRejectOrder=async id=>{const rationale=document.getElementById('or_'+id)?.value?.trim()||'Ação descartada durante a ordenação humana.';try{await authFetch('motor-order-actions','POST',{action:'REJECT_CANDIDATE',case_id:currentId,candidate_id:id,validation_rationale:rationale});YM.toast('Ação descartada.');await openCase(currentId)}catch(e){YM.toast(e.message||String(e),true)}};
  window.vosCreateOrder=async()=>{const candidate_action=document.getElementById('vosg_oa')?.value?.trim(),rationale=document.getElementById('vosg_or')?.value?.trim(),impact_on_destination=document.getElementById('vosg_oi')?.value?.trim(),not_now=Boolean(document.getElementById('vosg_on')?.checked);if(!candidate_action||!rationale)return YM.toast('Descreva a ação e por que ela faz sentido.',true);try{await authFetch('motor-order-actions','POST',{action:'CREATE_CANDIDATE',case_id:currentId,candidate_action,rationale,impact_on_destination,not_now});YM.toast('Ação candidata adicionada.');await openCase(currentId)}catch(e){YM.toast(e.message||String(e),true)}};

  const baseOpenGuided=openCase;
  openCase=async function(id){await baseOpenGuided(id);renderGuided()};window.openCase=openCase;
  const baseRefresh=document.getElementById('refresh')?.onclick;if(document.getElementById('refresh'))document.getElementById('refresh').onclick=async()=>{if(baseRefresh)await baseRefresh();if(currentId)await openCase(currentId)};
  setTimeout(()=>{if(currentId)renderGuided()},450);
})();